/* ============ PINYIN / ZHUYIN ============ */
const TONE_V = { a: 'āáǎàa', e: 'ēéěèe', i: 'īíǐìi', o: 'ōóǒòo', u: 'ūúǔùu', 'ü': 'ǖǘǚǜü' };
function markSyl(s) {
  const m = /^([a-zü]+)([1-5])$/i.exec(s || '');
  if (!m) return s || '';
  const base = m[1].toLowerCase().replace(/v/g, 'ü'); const t = +m[2];
  if (t === 5) return base;
  let idx = -1;
  if (base.includes('a')) idx = base.indexOf('a');
  else if (base.includes('e')) idx = base.indexOf('e');
  else if (base.includes('ou')) idx = base.indexOf('o');
  else for (let i = base.length - 1; i >= 0; i--) if ('iouü'.includes(base[i])) { idx = i; break; }
  if (idx < 0) return base;
  return base.slice(0, idx) + TONE_V[base[idx]][t - 1] + base.slice(idx + 1);
}
