    <div class="sit-top"><span class="cseal" data-cat="${s.cat}" aria-hidden="true" lang="zh-Hant">${esc([...s.zh][0])}</span><div class="meta">${lvlChip(s.lvl)}<span class="chip">${s.min} min</span></div></div>
