function demoPanel() {
  const d = UI.demo;
  const opts = [['Do you want it spicy?', 1], ['Do you want rice?', 0], ['Do you want a bag?', 0]];
  let h = `<div class="eyebrow">What does this mean?</div><div class="qz-opts">${opts.map((o, k) => {
    const cls = d.done ? (o[1] ? 'right' : 'dim') : (d.wrong.includes(k) ? 'wrong' : '');
    return `<button type="button" class="dopt ${cls}" data-act="demo" data-k="${k}" ${d.done || d.wrong.includes(k) ? 'disabled' : ''}><span class="k">${'ABC'[k]}</span>${o[0]}</button>`;
  }).join('')}</div>`;
  if (!d.done && d.wrong.length) h += `<div class="verdict no"><i>✕</i>Not quite.</div><p class="muted" style="margin-top:-6px">Listen for <b lang="zh-Hant">辣</b> (là). It means spicy. Try again.</p>`;
  if (d.done) {
    h += `<div class="verdict ok"><i>✓</i>Correct</div>
    <div class="ans-card">${phr('要辣嗎？', 'yao4 la4 ma5', 'Do you want it spicy?', 'xl')}
      <div class="ans-actions"><button type="button" class="btn pri" data-act="say" data-t="要辣嗎？">${I.play} Hear pronunciation</button><a class="btn ghost" href="#s.night-market" data-act="go" data-to="s.night-market">Learn this situation ${I.arrow}</a></div>
      <div class="follow"><div class="eyebrow">Your turn: answer the vendor</div>
        <div class="mini-opts">${SITS['night-market'].scene.nodes.n1.o.map((o, k) => `<button type="button" class="mini" data-act="demoreply" data-k="${k}"><b lang="zh-Hant">${esc(o[0])}</b><span>${esc(o[2])}</span></button>`).join('')}</div>
        ${d.reply != null ? demoReply(d.reply) : ''}
      </div>
    </div>`;
  }
  return h;
}
function demoReply(k) {
  const nodes = SITS['night-market'].scene.nodes; const o = nodes.n1.o[k]; const n = nodes[o[3]];
  return `<div class="reply"><div class="vendor-av" lang="zh-Hant" style="width:38px;height:38px">老闆</div><div style="flex:1">${phr(n.zh, n.py, n.en, 'sm')}</div>${playBtn(n.zh, 'sm')}</div>`;
}

