function contentSource(kind, id) {
  const x = (CONTENT_SOURCES[kind] && CONTENT_SOURCES[kind][id]) || {refs:[]};
  const rights = x.rights || 'original';
  const meta = rights === 'public'
    ? ['公版作品／本站教學編寫','gong1 ban3 zuo4 pin3 ben3 zhan4 jiao4 xue2 bian1 xie3','Public-domain source / educational adaptation']
    : rights === 'reference'
      ? ['名稱引用／不重製受保護內容','ming2 cheng1 yin3 yong4 bu4 zhong4 zhi4 shou4 bao3 hu4 nei4 rong2','Referential use / no protected content reproduced']
      : ['本站原創教學文字','ben3 zhan4 yuan2 chuang4 jiao4 xue2 wen2 zi4','Original educational text'];
  const note = x.note || (x.refs && x.refs.length
    ? '正文由本站自行撰寫；外部來源只用來查核事實與提供延伸閱讀，不大段轉載原文。'
    : '正文由本站自行撰寫，沒有轉載外部文章原文。');
  const en = x.en || (x.refs && x.refs.length
    ? 'The text is written by this site. External links are used for factual verification and further reading, not for reproducing source text.'
    : 'This teaching text is written by this site and does not reproduce an external article.');
  const links = (x.refs || []).map(r => `<a class="source-link" href="${esc(r[2])}" target="_blank" rel="noopener noreferrer"><span><b>${esc(r[0])}</b><small>${esc(r[1])}</small></span><span class="arrow" aria-hidden="true">↗</span></a>`).join('');
  return `<section class="source-panel" aria-label="Sources and copyright"><div class="source-top"><div>${triMini('來源與版權','lai2 yuan2 yu3 ban3 quan2','Sources & copyright','sm')}</div><span class="source-status">${rights === 'public' ? 'PUBLIC DOMAIN' : rights === 'reference' ? 'REFERENCE ONLY' : 'ORIGINAL'}</span></div>${triMini(meta[0],meta[1],meta[2],'sm')}<div class="source-note">${triMini(note,autoPy(note),en,'sm')}</div>${links ? `<div class="source-links">${links}</div>` : ''}</section>`;
}
function sourcePolicyBox() {
  const acadN = (typeof ACAD_UNITS !== 'undefined' && ACAD_UNITS.length) ? ACAD_UNITS.length : 167;
  return `<div class="source-policy"><b>來源與引用 Sources & quotation.</b> 文化文章與閱讀內容皆標示來源。文學單元若有可核對的原文索引，會提供 2–3 句短摘錄，題目只針對眼前摘錄做文意理解；找不到可核對全文入口的作品不做假引用。闖關學院目前共 ${acadN} 單元。</div>`;
}

/* ---------- CULTURE ---------- */
function vCulture() {
  return `<div class="view wrap culture-view">
  <header class="culture-mast">
    <div class="culture-mast-copy"><div class="eyebrow">Culture journal · Taiwan</div><h1 class="culture-title serif-zh" lang="zh-Hant">文化</h1><p class="culture-deck">從語言旁邊讀台灣。不是百科全書，而是把習慣、規矩、日常儀式與說話方式放回它們真正發生的生活裡。</p><p class="culture-deck-en">The context behind the words — short editorial reads on the habits and rituals that shape everyday Mandarin in Taiwan.</p></div>
    <div class="culture-mark" aria-hidden="true"><span>文</span><small>TAIWAN / CULTURE</small></div>
  </header>
  ${sourcePolicyBox()}
  <div class="art-grid culture-grid">${ARTICLES.map((a, i) => `<a class="card spot art-card culture-card rise ${i === 0 ? 'is-feature' : ''}" style="--i:${i}" href="#a.${a.id}" data-act="go" data-to="a.${a.id}" data-vt><div class="art-cover" data-c="${a.color}" style="--n:${[...a.zh].length}"><span class="culture-no">${String(i + 1).padStart(2, '0')}</span><b lang="zh-Hant">${a.zh}</b><small>${esc(pyLine(a.zh, autoPy(a.zh)))}</small><small lang="zh-Hant">${esc(zyLine(a.zh, autoPy(a.zh)))}</small></div><div class="art-meta"><div class="eyebrow">${esc(a.kicker)} · ${a.min} MIN</div><h3>${esc(a.en)}</h3><p>${esc(a.lead.split('. ')[0])}.</p><span class="culture-read">READ STORY <i aria-hidden="true">↗</i></span></div></a>`).join('')}</div>
  ${foot()}</div>`;
}
function inlineZh(t) { return esc(t).replace(/([\p{Script=Han}ㄅ-ㄯ]+)/gu, '<span class="zh-inline" lang="zh-Hant">$1</span>'); }
function vArticle(id) {
  const a = ARTI[id]; if (!a) return vCulture();
  const secs = a.sec.map((s, i) => {
    let h = `<section class="art-sec" id="sec-${i}"><h2>${inlineZh(s.h)}</h2>${s.p.map((p) => `<p>${inlineZh(p)}</p>`).join('')}`;
    if (s.ex) h += `<div class="ex-list">${s.ex.map((e) => `<div class="ex">${phr(e[0], e[1], e[2], 'md')}<div class="audio-row">${playBtn(e[0])}</div></div>`).join('')}</div>`;
    if (s.table) h += `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Say</th><th>Reading</th><th>Meaning</th><th>Roughly</th><th><span class="sr">Play</span></th></tr></thead><tbody>${s.table.map((r) => `<tr><td class="zh" lang="zh-Hant">${hz(r[0], r[1])}</td><td><div class="py">${esc(pyLine(r[0], r[1]))}</div><div class="zy" lang="zh-Hant">${esc(zyLine(r[0], r[1]))}</div></td><td>${esc(r[2])}</td><td class="v">${esc(r[3])}</td><td>${playBtn(r[0], 'sm')}</td></tr>`).join('')}</tbody></table></div>`;
    return h + '</section>';
  }).join('');
  const nextLink = a.drill ? `<a class="btn pri" href="#p.${a.drill}" data-act="go" data-to="p.${a.drill}">Try ${esc(DRI[a.drill].t)} ${I.arrow}</a>` : `<a class="btn pri" href="#s.${a.sit}" data-act="go" data-to="s.${a.sit}">Practice: ${esc(SITS[a.sit].en)} ${I.arrow}</a>`;
  return `<div class="view wrap culture-article-view">
  <nav class="crumbs" aria-label="Breadcrumb"><button type="button" data-act="go" data-to="culture">Culture</button><span>/</span><span>${esc(a.kicker)}</span></nav>
  <div class="card art-hero" data-vt-target><div class="art-cover" data-c="${a.color}"><b lang="zh-Hant">${a.zh}</b><small>${esc(pyLine(a.zh, autoPy(a.zh)))}</small><small lang="zh-Hant">${esc(zyLine(a.zh, autoPy(a.zh)))}</small><small>${esc(a.en)}</small></div></div>
  <div class="article">
    <aside class="art-tools glass" aria-label="Reading tools">
      <div class="prog"><svg viewBox="0 0 36 36" aria-hidden="true"><circle class="bg" cx="18" cy="18" r="15"/><circle class="fg" id="aring" cx="18" cy="18" r="15" stroke-dasharray="94.25" stroke-dashoffset="94.25"/></svg><span id="apct">0%</span></div>
      <h4>Contents</h4><div class="toc" id="toc">${a.sec.map((s, i) => `<button type="button" data-act="toc" data-i="${i}">${esc(s.h)}</button>`).join('')}</div>
      <h4>Text size</h4><div class="fs-row"><button type="button" data-act="afs" data-d="-1" aria-label="Smaller text">A−</button><button type="button" data-act="afs" data-d="1" aria-label="Larger text">A+</button></div>
      <h4>Chinese font</h4><div class="gs seg" data-gs="afont" data-i="${document.documentElement.classList.contains('zh-serif') ? 1 : 0}" style="width:100%"><div class="gs-row" style="flex:1"><button type="button" style="flex:1">黑體<span class="en-s">&nbsp;Sans</span></button><button type="button" style="flex:1">明體<span class="en-s">&nbsp;Serif</span></button></div></div>
    </aside>
    <article class="art-body culture-copy" id="abody" style="--afs:${UI.afs || 17}px">
      <div class="eyebrow">${esc(a.kicker)} · ${a.min} min read</div>
      <h1 class="h2" style="margin-top:10px">${esc(a.en)}</h1>
      <p class="lead">${inlineZh(a.lead)}</p>
      ${secs}
      ${contentSource('culture', a.id)}
      <div class="card art-next"><div><div class="eyebrow">Put it to use</div><p style="margin-top:6px;color:var(--text-2)">Practice these phrases in a real situation.</p></div>${nextLink}</div>
    </article>
  </div>
  ${foot()}</div>`;
}

/* ---------- PRACTICE ---------- */
function vPractice() {
  return `<div class="view wrap">
  <div class="sec-head"><div><div class="eyebrow">Practice · <span class="zh-font">練習</span></div><h1 class="h2" style="margin-top:8px">Short drills, real phrases</h1><p class="lede">Each drill takes about two minutes. Questions come from the question bank, so every round is different.</p></div></div>
  <div class="drill-grid">${DRILLS.map((d, i) => `<a class="card spot drill rise" style="--i:${i}" href="#p.${d.id}" data-act="go" data-to="p.${d.id}"><div class="top"><span class="glyph" lang="zh-Hant">${d.g}</span>${S.best[d.id] != null ? `<span class="best">Best ${S.best[d.id]}/${d.id === 'flash' ? '12' : '8'}</span>` : '<span class="chip">New</span>'}</div><h3>${d.t}</h3><p>${esc(d.d)}</p></a>`).join('')}</div>
  <section class="sec"><div class="sec-head"><div><div class="eyebrow">Or practice a situation</div><h2 class="h2" style="margin-top:8px">Pick up where you are</h2></div></div>
  <div class="sit-grid">${FIRST_WEEK.slice(0, 4).map(sitCard).join('')}</div></section>
  ${foot()}</div>`;
}
function vDrill(id) {
  const d = DRI[id]; if (!d) return vPractice();
  return `<div class="view wrap">
  <nav class="crumbs" aria-label="Breadcrumb"><button type="button" data-act="go" data-to="practice">Practice</button><span>/</span><span>${d.t}</span></nav>
  <div class="sec-head"><div style="display:flex;gap:16px;align-items:center"><span class="dglyph" lang="zh-Hant">${d.g}</span><div><h1 class="h2">${d.t}</h1><p class="lede">${esc(d.d)}</p></div></div></div>
  <div class="card qz-host" id="drill-host" style="max-width:760px"></div>
  ${foot()}</div>`;
}
/* flashcards */
let FC = null;
function startFlash(host) {
  const ids = new Set(); PH.forEach((p) => { if (S.saved[p.id] || S.learned[p.id] || S.heard[p.id]) ids.add(p.id); });
  const base = FIRST_WEEK.flatMap((sid) => PH.filter((p) => p.sid === sid).map((p) => p.id));
  const deck = shuffle([...ids]).slice(0, 12);
  for (const id of shuffle(base)) { if (deck.length >= 12) break; if (!deck.includes(id)) deck.push(id); }
  FC = { host, deck, base: deck.length, again: 0, i: 0, got: 0, flip: false }; renderFlash();
}
function renderFlash() {
  const f = FC; const p = PHI[f.deck[f.i]];
  if (!p) {
    S.best.flash = Math.max(S.best.flash || 0, f.got); save();
    f.host.innerHTML = `<div class="qz-done rise"><div class="ring" style="--p:0"><div><b data-count="${f.got}">0</b><span>of ${f.base}</span></div></div><h3 class="h2">Deck done</h3><div class="xp">+${f.got * 2} XP</div><div class="ans-actions"><button type="button" class="btn pri" data-act="fcagain">New deck</button><a class="btn ghost" href="#practice" data-act="go" data-to="practice">All drills</a></div></div>`;
    ringTo($('.ring', f.host), Math.round((f.got / f.base) * 100)); countUp($('[data-count]', f.host)); toast('Deck finished', f.got * 2); return;
  }
  f.flip = false;
  f.host.innerHTML = `<div class="qz"><div class="qz-top"><div class="qz-bar"><i style="width:${(f.i / f.deck.length) * 100}%"></i></div><span class="qz-count">${f.i + 1} / ${f.deck.length}</span></div>
  <div class="fc-stage"><div class="fc" id="fc" data-act="fcflip" role="button" tabindex="0" aria-label="Flip card">
    <div class="fc-face"><div class="phr xl"><div class="zh" lang="zh-Hant">${hz(p.zh, p.py)}</div></div><span class="hint">Tap the card to see the reading and meaning</span></div>
    <div class="fc-face fc-back">${phr(p.zh, p.py, p.en, 'lg')}<span class="small muted" lang="zh-Hant">${esc(SITS[p.sid].zh)} · ${esc(SITS[p.sid].en)}</span></div>
  </div></div>
  <div class="fc-actions">${playBtn(p.zh)}<button type="button" class="btn ghost" data-act="fcnext" data-ok="0">Again later</button><button type="button" class="btn pri" data-act="fcnext" data-ok="1">${I.check} I know it</button></div></div>`;
}

/* ---------- PROGRESS ---------- */
const BADGES = [
  { g: '辣', t: 'First bite', d: 'Finish the night market scene', ok: () => S.scenes['night-market'] },
  { g: '糖', t: 'Half sugar, less ice', d: 'Finish the bubble tea scene', ok: () => S.scenes['bubble-tea'] },
  { g: '車', t: 'Garbage runner', d: 'Finish the garbage truck scene', ok: () => S.scenes.garbage },
  { g: '讀', t: 'Always replies', d: 'Finish the LINE scene', ok: () => S.scenes.line },
  { g: '景', t: 'Scene regular', d: 'Finish five different scenes', ok: () => Object.keys(S.scenes).length >= 5 },
  { g: 'ㄅ', t: 'Zhuyin reader', d: 'Score 6 or more in Zhuyin match', ok: () => (S.best.zhuyin || 0) >= 6 },
  { g: '台', t: 'Local ear', d: 'Score 7 or more in Taiwan or textbook', ok: () => (S.best.twcn || 0) >= 7 },
  { g: '藏', t: 'Collector', d: 'Save 10 phrases or words', ok: () => savedCount() >= 10 },
  { g: '三', t: 'Three-day streak', d: 'Practice three days in a row', ok: () => streak() >= 3 },
];
function weekChart() {
  const days = []; const d = new Date(); d.setDate(d.getDate() - 6);
  for (let i = 0; i < 7; i++) { days.push({ k: dkey(d), l: d.toLocaleDateString('en', { weekday: 'short' }), v: S.days[dkey(d)] || 0 }); d.setDate(d.getDate() + 1); }
  const max = Math.max(50, ...days.map((x) => x.v)); const W = 560, H = 190, top = 26, bot = 28, bw = 44, gap = (W - 7 * bw) / 6;
  const bars = days.map((x, i) => { const h = Math.round((x.v / max) * (H - top - bot)); const xx = i * (bw + gap); const y = H - bot - h; const isT = i === 6;
    return `<rect x="${xx}" y="${H - bot - (H - top - bot)}" width="${bw}" height="${H - top - bot}" rx="10" class="bar-bg"/>${h > 0 ? `<rect x="${xx}" y="${y}" width="${bw}" height="${h}" rx="10" class="${isT ? 'bar-t' : 'bar-r'}"/>` : ''}<text x="${xx + bw / 2}" y="${Math.max(top - 8, y - 8)}" text-anchor="middle" class="${x.v ? 'lbl' : ''}">${x.v || ''}</text><text x="${xx + bw / 2}" y="${H - 8}" text-anchor="middle" class="${isT ? 'lbl' : ''}">${isT ? 'Today' : x.l}</text>`; }).join('');
  const empty = days.every((x) => !x.v) ? `<div class="chart-empty"><b>Your week starts with one answer.</b><span>Play a stage or a quick drill and your XP shows up here.</span><a class="btn pri sm" href="#practice" data-act="go" data-to="practice">Draw a card ${I.arrow}</a></div>` : '';
  return `<div class="chart-wrap${empty ? ' is-empty' : ''}"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="XP earned over the last seven days">${bars}</svg>${empty}</div>`;
}
function vProgress() {
  const lv = level(); const nextL = LEVELS[lv + 1]; const learned = learnedCount(); const scenes = Object.keys(S.scenes).length;
  const toNext = nextL ? nextL[0] - S.xp : 0;
  return `<div class="view wrap">
  <div class="sec-head"><div><div class="eyebrow">Progress · <span class="zh-font">進度</span></div><h1 class="h2" style="margin-top:8px">Your Taiwan Mandarin</h1><p class="lede">${S.xp ? `You’re a <b lang="zh-Hant">${LEVELS[lv][1]}</b> (${LEVELS[lv][2]}).${nextL ? ` ${toNext} XP to ${LEVELS[lv + 1][2]}.` : ''}` : 'Your progress starts with your first answer. The night market demo on Home is a good first step.'} Progress is saved in this browser.</p></div></div>
  <div class="stats">
    <div class="card stat rise"><span class="k">Total XP</span><span class="v" data-count="${S.xp}">0</span><span class="s">${LEVELS[lv][2]}</span></div>
    <div class="card stat rise" style="--i:1"><span class="k">Day streak</span><span class="v" data-count="${streak()}">0</span><span class="s">${streak() === 1 ? 'day' : 'days'} in a row</span></div>
    <div class="card stat rise" style="--i:2"><span class="k">Phrases learned</span><span class="v" data-count="${learned}">0</span><span class="s">of ${PH.length}</span></div>
    <div class="card stat rise" style="--i:3"><span class="k">Scenes finished</span><span class="v" data-count="${scenes}">0</span><span class="s">of ${SCENE_COUNT}</span></div>
  </div>
  ${gameProgressCard()}
  ${Daily.panel()}
  <div class="prog-grid">
    <div class="card panel chart rise"><h3>XP this week</h3>${weekChart()}</div>
    <div class="card panel rise" style="--i:1"><h3>XP rank <span class="zh-font muted">稱號</span></h3><div class="ladder">${LEVELS.map((l, i) => `<div class="rung ${i === lv ? 'now' : ''} ${i < lv ? 'got' : ''}"><span class="zh" lang="zh-Hant">${l[1]}</span><span class="en">${l[2]}</span><span class="req">${l[0]} XP</span></div>`).join('')}</div></div>
  </div>
  <div class="prog-stack">
    <div class="card panel rise life-panel"><h3>By part of life</h3><div class="cbars">${CATS.map((c) => { const ss = SIT.filter((s) => s.cat === c.id); const p = Math.round(ss.reduce((a, s) => a + sitPct(s), 0) / ss.length); return `<div class="cbar">${catSeal(c.id)}<div><div style="display:flex;justify-content:space-between;font:600 14px var(--f-ui);margin-bottom:6px"><span>${c.en}</span></div><div class="bar"><i data-w="${p}"></i></div></div><b>${p}%</b></div>`; }).join('')}</div></div>
    <div class="card panel rise" style="--i:1"><h3>Badges <span class="small muted">${BADGES.filter((b) => b.ok()).length}/${BADGES.length}</span></h3><div class="badges">${BADGES.map((b) => { const ok = b.ok(); return `<div class="badge ${ok ? 'got' : ''}"><span class="b" lang="zh-Hant">${b.g}</span><b>${esc(b.t)}</b><span>${ok ? 'Earned' : esc(b.d)}</span></div>`; }).join('')}</div></div>
  </div>
  ${foot()}</div>`;
}

