/* ================= DEFENSIVE BOT / INJECTION GUARD =================
   Client-side code cannot make downloaded source secret. This is a non-destructive
   defense layer: crawler refusal hints, obvious automation blocking, suspicious-input
   rejection, short local lockouts and a local audit trail. It never attacks a visitor. */
const SecurityGuard = (() => {
  const LOG='xiantaiwen-security-log-v1', LOCK='xiantaiwen-security-lock-v1';
  const bot=/(?:bot|crawler|spider|scrapy|wget|curl|python-requests|httpclient|headless|phantom|selenium|playwright|puppeteer|gptbot|chatgpt-user|claudebot|claude-web|anthropic-ai|bytespider|ccbot|cohere-ai|perplexitybot|google-extended|amazonbot|facebookbot)/i;
  const suspicious=/(?:ignore\s+(?:all|any|the)?\s*(?:previous|prior|above)|system\s*(?:prompt|message)|developer\s*(?:prompt|message)|prompt\s*injection|jailbreak|reveal\s+(?:the\s+)?(?:prompt|instructions)|dump\s+(?:the\s+)?(?:prompt|config)|(?:delete|remove|erase|wipe)\s+.{0,24}(?:admin|server|file|database)|rm\s+-rf|format\s+[a-z]:|drop\s+table|<\s*script\b|javascript\s*:|data\s*:\s*text\/html|169\.254\.169\.254|\.\.[\\/])/i;
  let strikes=0;
  function log(kind,detail=''){
    try{const a=JSON.parse(localStorage.getItem(LOG)||'[]');a.unshift({time:new Date().toISOString(),kind,detail:String(detail).slice(0,180)});localStorage.setItem(LOG,JSON.stringify(a.slice(0,20)));}catch(_){}
  }
  function automated(){
    try{return !!navigator.webdriver || bot.test(navigator.userAgent||'');}catch(_){return false;}
  }
  function blockIfBot(){
    if(!automated())return false;
    log('bot-block',navigator.userAgent||'');
    const d=document.createElement('div');d.className='security-block';d.innerHTML='<div><span class="seal" lang="zh-Hant">閒</span><h1 class="h2">Automated access denied</h1><p class="lede" style="margin:10px auto 0">本網站不授權自動化爬取、模型訓練或批次擷取。一般瀏覽器使用者不受影響。</p></div>';
    document.body.replaceChildren(d);return true;
  }
  function locked(){try{return +(localStorage.getItem(LOCK)||0)>Date.now();}catch(_){return false;}}
  function inspect(text,where='input'){
    const v=String(text||'');
    if(locked())return {ok:false,reason:'temporarily-locked'};
    if(!suspicious.test(v))return {ok:true};
    strikes++;log('suspicious-input',where+': '+v);
    if(strikes>=3){try{localStorage.setItem(LOCK,String(Date.now()+30000));}catch(_){}}
    toast(strikes>=3?'可疑自動化指令已封鎖 · 30 秒保護鎖':'可疑指令已封鎖；本頁不會執行系統或管理員命令');
    return {ok:false,reason:'suspicious'};
  }
  return {automated,blockIfBot,inspect,log};
})();
window.SecurityGuard=SecurityGuard;

/* ================= SEARCH ================= */
function openSearch() {
  closeOverlays(); const ov = $('#search'); ov.hidden = false;
  const i = $('#sq'); i.value = ''; runSearch(); setTimeout(() => i.focus(), 30);
}
function runSearch() {
  const raw = $('#sq').value.trim(); const box = $('#sres');
  if (raw && window.SecurityGuard && !SecurityGuard.inspect(raw,'search').ok) { box.innerHTML = '<div class="s-hint">這段輸入被安全防護攔截。</div>'; return; }
  if (raw && window.EasterEggs) EasterEggs.search(raw);
  const q = raw.toLowerCase(); const qn = stripMarks(q);
  if (!q) { box.innerHTML = `<div class="s-hint">Search situations, phrases, dictionary words, Taiwanese, readings and practice stages.<div class="chips">${['捷運', 'bubble tea', 'spicy', 'lese', '歹勢', 'garbage', '請假'].map((t) => `<button type="button" data-act="sq" data-q="${esc(t)}">${esc(t)}</button>`).join('')}</div></div>`; return; }
  const m = (zh, en, py) => (zh && zh.includes(raw)) || (en && en.toLowerCase().includes(q)) || (py && qn.length > 1 && toneless(py).includes(qn));
  const groups = [];
  const sits = SIT.filter((s) => m(s.zh, s.en + ' ' + s.blurb, s.py)).slice(0, 5);
  if (sits.length) groups.push(['Situations', sits.map((s) => `<button type="button" class="s-item" data-act="sgo" data-to="s.${s.id}"><span class="z" lang="zh-Hant">${esc(s.zh)}</span><span class="i"><b>${esc(s.en)}</b><span>${esc(CAT[s.cat].en)} · ${esc(s.blurb)}</span></span></button>`)]);
  const phs = PH.filter((p) => m(p.zh, p.en, p.py)).slice(0, 6);
  if (phs.length) groups.push(['Phrases', phs.map((p) => `<button type="button" class="s-item" data-act="sgo" data-to="s.${p.sid}" data-tab="phrases"><span class="z" lang="zh-Hant">${esc(p.zh)}</span><span class="i"><b>${esc(p.en)}</b><span>${esc(pyLine(p.zh, p.py))} · ${esc(SITS[p.sid].en)}</span></span></button>`)]);
  const ds = DICT.filter((d) => m(d.zh, d.en, d.py) || (d.cn && (d.cn[0].includes(raw) || d.cn[1].includes(raw)))).slice(0, 6);
  if (ds.length) groups.push(['Dictionary', ds.map((d) => `<button type="button" class="s-item" data-act="sgo" data-dict="${d.id}"><span class="z" lang="zh-Hant">${esc(d.zh)}</span><span class="i"><b>${esc(d.en)}</b><span>${esc(pyLine(d.zh, d.py))} · ${esc(TLABEL[d.t][0])}</span></span></button>`)]);
  const ts = TAI.filter((t) => (t.tw.includes(raw) || t.en.toLowerCase().includes(q) || stripMarks(t.tl).replace(/-/g, '').includes(qn) || t.md.includes(raw))).slice(0, 4);
  if (ts.length) groups.push(['Taiwanese', ts.map((t) => `<button type="button" class="s-item" data-act="sgo" data-to="taiwanese"><span class="z" lang="nan-Hant">${esc(t.tw)}</span><span class="i"><b>${esc(t.en)}</b><span>${esc(t.tl)} · Mandarin ${esc(t.md)}</span></span></button>`)]);
  const as = ARTICLES.filter((a) => m(a.zh, a.en + ' ' + a.lead) || a.sec.some((s) => s.h.toLowerCase().includes(q))).slice(0, 3);
  if (as.length) groups.push(['Culture', as.map((a) => `<button type="button" class="s-item" data-act="sgo" data-to="a.${a.id}"><span class="z" lang="zh-Hant">${esc(a.zh)}</span><span class="i"><b>${esc(a.en)}</b><span>${esc(a.kicker)} · ${a.min} min read</span></span></button>`)]);
  const rs = GAME.readings.filter((r) => m(r.zh, r.en + ' ' + r.tag + ' ' + r.intro, r.zhpy) || r.ps.some((p) => p[0].includes(raw))).slice(0, 4);
  if (rs.length) groups.push(['Readings', rs.map((r) => `<button type="button" class="s-item" data-act="sgo" data-to="r.${r.id}"><span class="z" lang="zh-Hant">${esc(r.zh)}</span><span class="i"><b>${esc(r.en)}</b><span>第 ${r.id.slice(1)} 篇 · ${r.lvl} · ${esc(r.tag)}</span></span></button>`)]);
  const acs = Academy.search(raw, q);
  if (acs.length) groups.push(['Academy · 闖關學院', acs]);
  const gs = GAME.stages.filter((s) => m(s.zh + s.place, s.en)).slice(0, 4);
  if (gs.length) groups.push(['Practice stages', gs.map((s) => { const ok = G().cleared[s.id]; return `<button type="button" class="s-item" data-act="sgo" data-to="${ok ? 'g.' + s.id : 'practice'}"><span class="z" lang="zh-Hant">${esc(s.zh)}</span><span class="i"><b>${esc(s.en)}</b><span>Lv.${s.lv} · ${esc(s.place)} · ${ok ? 'Cleared, replay' : 'Draw it from the card box'}</span></span></button>`; })]);
  box.innerHTML = groups.length ? groups.map((g) => `<div class="s-group">${g[0]}</div>${g[1].join('')}`).join('') : `<div class="s-hint">Nothing matches “${esc(raw)}”. Try English, characters, or toneless pinyin like <b>xiexie</b>.</div>`;
  const first = $('.s-item', box); if (first) first.classList.add('act');
}
function searchKeys(e) {
  const items = $$('#sres .s-item'); if (!items.length) return;
  let i = items.findIndex((x) => x.classList.contains('act'));
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); items[i] && items[i].classList.remove('act'); i = clamp(i + (e.key === 'ArrowDown' ? 1 : -1), 0, items.length - 1); items[i].classList.add('act'); items[i].scrollIntoView({ block: 'nearest' }); }
  if (e.key === 'Enter') { e.preventDefault(); (items[i] || items[0]).click(); }
}

/* ================= READING LENS ================= */
const Lens = {
  on: false, x: 0, y: 0, R: 78, scale: 1.75, el: null, view: null, cl: null, read: null, mo: null, t: 0,
  build() {
    this.el = $('#lens'); this.view = $('.lens-view', this.el); this.read = $('.lens-read', this.el);
    let drag = null;
    this.el.addEventListener('pointerdown', (e) => {
      if (e.target.closest('.lens-x')) return; e.preventDefault();
      try { this.el.setPointerCapture(e.pointerId); } catch (_) { /* noop */ }
      drag = { sx: e.clientX, sy: e.clientY, x0: this.x, y0: this.y, moved: false }; this.el.classList.add('drag');
    });
    let lensMoveRAF=0, lensMoveEvent=null;
    this.el.addEventListener('pointermove', (e) => {
      if (!drag) return;
      lensMoveEvent=e;
      if(lensMoveRAF) return;
      lensMoveRAF=requestAnimationFrame(()=>{
        lensMoveRAF=0;
        const ev=lensMoveEvent; if(!ev || !drag) return;
        const dx = ev.clientX - drag.sx, dy = ev.clientY - drag.sy;
        if (Math.abs(dx) + Math.abs(dy) > 4) drag.moved = true;
        this.x = clamp(drag.x0 + dx, -this.R, innerWidth - this.R); this.y = clamp(drag.y0 + dy, 40 - this.R, innerHeight - this.R);
        this.pos(); this.update();
      });
    }, {passive:true});
    const end = () => { if (!drag) return; const moved = drag.moved; drag = null; this.el.classList.remove('drag'); if (!moved && this.cur) { say(this.cur, false, null, 'phonetic:'+this.cur+':'+(this.curS||'')); } };
    this.el.addEventListener('pointerup', end); this.el.addEventListener('pointercancel', end);
    this.mo = new MutationObserver(() => { clearTimeout(this.t); this.t = setTimeout(() => { if (this.on) { this.snap(); this.update(); } }, 140); });
    const lx=$('.lens-x', this.el); if(lx) lx.addEventListener('click', () => this.close());
    window.addEventListener('resize', () => { if (this.on) { this.snap(); this.update(); } });
  },
  open() {
    if (!this.el) this.build();
    this.on = true; this.el.hidden = false;
    this.x = Math.round(innerWidth * 0.62 - this.R); this.y = Math.round(innerHeight * 0.42 - this.R);
    this.pos(); this.snap(); this.update();
    this.mo.observe($('#app'), { childList: true, subtree: true, attributes: true, attributeFilter: ['class', 'aria-pressed'] });
    $$('[data-act="lens"]').forEach((b) => b.setAttribute('aria-pressed', 'true'));
    toast('拖動圓形放大鏡閱讀中文；點一下可聽發音。');
  },
  close() { this.on = false; if (this.el) this.el.hidden = true; if (this.mo) this.mo.disconnect(); $$('[data-act="lens"]').forEach((b) => b.setAttribute('aria-pressed', 'false')); },
  toggle() { this.on ? this.close() : this.open(); },
  refresh() { if (this.on) { this.snap(); this.update(); } },
  pos() { this.el.style.translate = `${this.x}px ${this.y}px`; },
  snap() {
    const app = $('#app'); if (this.cl) this.cl.remove();
    const c = app.cloneNode(true); c.removeAttribute('id'); $$('[id]', c).forEach((n) => n.removeAttribute('id'));
    // Canvas/video/iframe clones frequently render blank or corrupted in iOS compositing.
    // Replace them with neutral boxes inside the optical clone rather than showing a broken layer.
    $$('canvas,video,iframe,audio,object,embed', c).forEach((n) => { const p=document.createElement('div'); p.className='lens-media-placeholder'; const r=n.getBoundingClientRect?.(); if(r&&r.height)p.style.height=Math.min(220,Math.max(36,r.height))+'px'; n.replaceWith(p); });
    $$('script,style,link,source', c).forEach((n)=>n.remove());
    c.className = 'lens-clone'; c.setAttribute('aria-hidden', 'true'); c.style.width = app.offsetWidth + 'px'; c.inert = true;
    this.view.replaceChildren(c); this.cl = c;
  },
  update() {
    if (!this.cl) return;
    const r = $('#app').getBoundingClientRect(); const cx = this.x + this.R, cy = this.y + this.R;
    const px = cx - r.left, py = cy - r.top, s = this.scale;
    this.cl.style.transform = `translate(${(this.R - px * s).toFixed(1)}px, ${(this.R - py * s).toFixed(1)}px) scale(${s})`;
    this.readAt(cx, cy);
  },
  readAt(cx, cy) {
    this.el.style.pointerEvents = 'none';
    const el = document.elementFromPoint(cx, cy);
    if (window.EasterEggs && CUR?.v === 'about' && el && el.closest && el.closest('.about-kicker .seal, .about-manifesto-mark')) EasterEggs.lensAbout();
    let ch = null, s = null; this.ctxText = null;
    const h = el && el.closest && el.closest('.h');
    if (h) { ch = h.textContent; s = h.dataset.s; const z = h.parentElement && h.parentElement.closest('[lang^="zh"]'); if (z) this.ctxText = z.textContent.replace(/^「|」$/g, '').trim(); }
    else {
      let node = null, off = 0;
      try {
        if (document.caretPositionFromPoint) { const p = document.caretPositionFromPoint(cx, cy); if (p) { node = p.offsetNode; off = p.offset; } }
        else if (document.caretRangeFromPoint) { const rg = document.caretRangeFromPoint(cx, cy); if (rg) { node = rg.startContainer; off = rg.startOffset; } }
      } catch (_) { /* noop */ }
      if (node && node.nodeType === 3) { const t = node.data; const c1 = t[off], c0 = t[off - 1]; ch = c1 && isHan(c1) ? c1 : c0 && isHan(c0) ? c0 : null; if (ch) s = CHAR[ch] || null; }
    }
    this.el.style.pointerEvents = '';
    if (ch === this.cur && s === this.curS) return;
    this.cur = ch; this.curS = s;
    this.read.innerHTML = ch ? `<span class="c" lang="zh-Hant">${ch}</span>${s ? `<span class="r"><b>${esc(markSyl(s))}</b><span lang="zh-Hant">${esc(zhuyin(s))}</span></span>` : '<span class="r"><b>—</b><span>not in this course yet</span></span>'}` : '<span class="hint">Drag over Chinese text</span>';
  },
};


/* ================= iOS AUDIO RECOVERY =================
   iOS can suspend AudioContext/media after Control Center, calls, silent-route changes,
   or returning from background. Recover on every real interaction, not only the first tap. */
let lastAudioRecovery=0;
function recoverAudioStack(){
  const now=performance.now(); if(now-lastAudioRecovery<180) return; lastAudioRecovery=now;
  try{
    setSoundOptIn(true);
    if(window.Soundscape) window.Soundscape.unlock(true);
    const c=AudioEng.ensure();
    if(c && c.state==='suspended') c.resume().catch(()=>{});
    if(window.speechSynthesis) try{window.speechSynthesis.resume();}catch(_){}
  }catch(_){}
}
['pointerdown','touchstart','click','keydown'].forEach(ev=>document.addEventListener(ev,recoverAudioStack,{capture:true,passive:true}));
window.addEventListener('pageshow',()=>setTimeout(recoverAudioStack,0));
window.addEventListener('focus',()=>setTimeout(recoverAudioStack,0));
document.addEventListener('visibilitychange',()=>{if(!document.hidden)setTimeout(recoverAudioStack,40)});

/* ================= DISPLACEMENT MAPS (glass refraction) ================= */
function dispMap(w, h, r, edge) {
  const c = document.createElement('canvas'); c.width = w; c.height = h; const x = c.getContext('2d'); const img = x.createImageData(w, h);
  for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) {
    const cxp = clamp(i, r, w - r), cyp = clamp(j, r, h - r); const dx = i - cxp, dy = j - cyp; const d = Math.hypot(dx, dy);
    const inside = r - d; const t = clamp(1 - inside / (r * edge), 0, 1); const k = t * t * (3 - 2 * t);
    const nx = d ? dx / d : 0, ny = d ? dy / d : 0; const o = (j * w + i) * 4;
    img.data[o] = 128 - nx * k * 127; img.data[o + 1] = 128 - ny * k * 127; img.data[o + 2] = 128; img.data[o + 3] = 255;
  }
  x.putImageData(img, 0, 0); return c.toDataURL();
}
function setupMaps() {
  try {
    const pm = $('#pillMap'); const pu = dispMap(200, 60, 30, 0.9); pm.setAttribute('href', pu); pm.setAttributeNS('http://www.w3.org/1999/xlink', 'href', pu);
  } catch (e) { /* canvas unavailable: glass still works without refraction */ }
}

