function syncThemeBtn() { $$('[data-act="theme"]').forEach((b) => { b.innerHTML = effectiveDark() ? I.sun : I.moon; b.setAttribute('aria-label', effectiveDark() ? 'Switch to light mode' : 'Switch to dark mode'); }); }
matchMedia('(prefers-color-scheme: dark)').addEventListener && matchMedia('(prefers-color-scheme: dark)').addEventListener('change', syncThemeBtn);

/* ================= INIT ================= */
function init() {
  // GitHub Pages/browser-safe: do not block page initialization based on User-Agent.
  // Crawler policy belongs in robots/meta/server controls; UA blocking can strand real/preview browsers on boot.
  // if(window.SecurityGuard && SecurityGuard.blockIfBot()) return;
  try{EasterEggs.init();SensorEggs.init();}catch(_){}
  setupMaps();
  $$('[data-icon]').forEach((b) => { b.innerHTML = I[b.dataset.icon] + (b.dataset.label ? `<span>${b.dataset.label}</span><kbd>⌘K</kbd>` : ''); });
  applySettings(); syncAvatar();
  navGS = GS($('#navLinks'), (i) => go(NAV[i]), true);
  tabGS = GS($('#tabs'), (i) => go(TABS[i]), true);
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => { navGS.relayout(); tabGS.relayout(); });
  $('#sq').addEventListener('input', runSearch); $('#sq').addEventListener('keydown', searchKeys);
  if (document.startViewTransition) document.documentElement.classList.add('has-vt');
  render(parse(location.hash));
  UIFX.init();
  const welcomed = Welcome.maybe();
  requestAnimationFrame(() => { const boot = $('#boot-screen'); if (boot) { boot.classList.add('out'); setTimeout(() => boot.remove(), 450); } });
  if (!welcomed) soundReminder();
}
/* one-time, non-blocking reminder to turn sound on (phones on silent / do-not-disturb) */
function soundReminder() {
  let seen = true; // sound now starts automatically on first interaction, so the reminder popup is no longer needed
  const el = $('#sound-reminder'); if (seen || !el) return;
  const done = (on) => { try { localStorage.setItem('xiantaiwen-sound-reminded', '1'); } catch (e) {} el.classList.remove('in'); setTimeout(() => { el.hidden = true; }, 350); if (on) { S.set.ambient=1; S.set.music=1; S.set.sfx=1; save(); applySettings(); setSoundOptIn(true); if(window.Soundscape) window.Soundscape.enableFromGesture(); const ctx = AudioEng.ensure(); if (ctx && ctx.state === 'suspended') ctx.resume(); say('歡迎光臨！', false); } };
  setTimeout(() => { el.hidden = false; requestAnimationFrame(() => el.classList.add('in')); }, 1400);
  $('#sound-ready').onclick = () => done(true); $('#sound-later').onclick = () => done(false);
}
let audioHiddenStopTimer=0;
document.addEventListener('visibilitychange', () => {
  clearTimeout(audioHiddenStopTimer);audioHiddenStopTimer=0;
  if (document.hidden) {
    // iOS can emit a very short hidden state while browser chrome / permission UI
    // changes. Do not kill an active sentence immediately; only stop after a real
    // background transition persists.
    audioHiddenStopTimer=setTimeout(()=>{if(document.hidden)AudioEng.stop();},1400);
  } else {
    try{if(window.speechSynthesis?.paused)window.speechSynthesis.resume();}catch(_){}
    if (AudioEng.ctx && AudioEng.ctx.state === 'suspended') AudioEng.ctx.resume().catch(() => {});
  }
});
window.addEventListener('pageshow', () => {
  clearTimeout(audioHiddenStopTimer);audioHiddenStopTimer=0;
  try{if(window.speechSynthesis?.paused)window.speechSynthesis.resume();}catch(_){}
  if (AudioEng.ctx && AudioEng.ctx.state === 'suspended') AudioEng.ctx.resume().catch(() => {});
});
