window.EasterEggs=EasterEggs;

/* ================= MOTION EASTER EGGS ================= */
const SensorEggs=(()=>{
  let started=false,asked=false,lastShake=0,faceSince=0,faceArmed=true,prev=null;
  const finite=(x)=>Number.isFinite(Number(x));
  function orient(e){
    const b=Number(e.beta),g=Number(e.gamma);if(!finite(b)||!finite(g))return;
    const down=Math.abs(b)>145&&Math.abs(g)<65;
    if(down){if(!faceSince)faceSince=performance.now();if(faceArmed&&performance.now()-faceSince>650){faceArmed=false;EasterEggs.faceDown();}}
    else{faceSince=0;if(Math.abs(b)<105)faceArmed=true;}
  }
  function motion(e){
    const n=performance.now();let mag=0;const a=e.acceleration;
    if(a&&finite(a.x)&&finite(a.y)&&finite(a.z))mag=Math.hypot(+a.x,+a.y,+a.z);
    else{const q=e.accelerationIncludingGravity;if(!q||!finite(q.x)||!finite(q.y)||!finite(q.z))return;const cur=[+q.x,+q.y,+q.z];if(prev)mag=Math.hypot(cur[0]-prev[0],cur[1]-prev[1],cur[2]-prev[2]);prev=cur;}
    if(mag>16.5&&n-lastShake>2600){lastShake=n;EasterEggs.shake();}
  }
  function start(){if(started)return;started=true;window.addEventListener('deviceorientation',orient,{passive:true});window.addEventListener('devicemotion',motion,{passive:true});}
  async function ask(){
    if(asked)return;asked=true;
    const req=[];
    try{if(typeof DeviceMotionEvent!=='undefined'&&typeof DeviceMotionEvent.requestPermission==='function')req.push(DeviceMotionEvent.requestPermission());}catch(_){}
    try{if(typeof DeviceOrientationEvent!=='undefined'&&typeof DeviceOrientationEvent.requestPermission==='function')req.push(DeviceOrientationEvent.requestPermission());}catch(_){}
    if(!req.length){start();return;}
    try{const r=await Promise.allSettled(req);if(r.some(x=>x.status==='fulfilled'&&x.value==='granted'))start();}catch(_){}
  }
  function init(){
    if(!matchMedia('(pointer:coarse)').matches){start();return;}
    const arm=()=>{ask();document.removeEventListener('pointerdown',arm,true);document.removeEventListener('touchend',arm,true);};
    document.addEventListener('pointerdown',arm,{capture:true,passive:true,once:true});
    document.addEventListener('touchend',arm,{capture:true,passive:true,once:true});
  }
  return {init};
})();

/* text with optional pinyin pair [text, py] */
function tx(p, opts = {}) {
  if (!p) return '';
  const [t, py] = p;
  if (!py) return esc(t);
  return opts.plain ? esc(t) : hz(t, py);
}
const LATIN = /[A-Za-z]{2,}/;
/* for mixed English + Chinese text: only annotate the Chinese chunks ("下一位 xià yī wèi") */
function hanChunks(t, py) {
  const syl = String(py || '').trim().split(/\s+/); let i = 0; const out = []; let cur = null;
  for (const ch of t) {
    if (isHan(ch)) { const s = syl[i++] || ''; if (!cur) { cur = { z: '', p: [], y: [] }; out.push(cur); } cur.z += ch; cur.p.push(markSyl(s)); cur.y.push(zhuyin(s)); }
    else cur = null;
  }
  return out;
}
function txRom(p) {
  if (p && p[1] && LATIN.test(p[0])) { const c = hanChunks(p[0], p[1]); return `<span class="py">${c.map((x) => `<b lang="zh-Hant">${esc(x.z)}</b> ${esc(x.p.join(' '))}`).join(' · ')}</span><span class="zy" lang="zh-Hant">${c.map((x) => `${esc(x.z)} ${esc(x.y.join(' '))}`).join(' · ')}</span>`; }
  return txRomPlain(p);
}
function txRomPlain(p) { if (!p || !p[1]) return ''; return `<span class="py">${esc(pyLine(p[0], p[1]))}</span><span class="zy" lang="zh-Hant">${esc(zyLine(p[0], p[1]))}</span>`; }

