function mountReading(id) {
  const r = GREAD[id]; RD = { id, t0: 0, iv: 0 };
  const host = $('#rq');
  new Quiz(host, () => r.qs.map((q) => ({
    ask: '閱讀測驗',
    prompt: `<div class="qz-ctx" lang="zh-Hant">${tx(q.p)}</div>${q.pg ? `<div class="small muted">${esc(q.pg)}</div>` : ''}`,
    options: shuffle(q.o.map((o) => ({ html: `<span class="zh-o" lang="zh-Hant">${esc(o.x[0])}</span>${o.g ? `<span class="small muted" style="display:block">${esc(o.g)}</span>` : ''}`, ok: o.ok }))),
    explain: q.ex ? `<p lang="zh-Hant">${tx(q.ex)}</p>` : '',
  })), {
    id: 'read:' + id,
    back: `<a class="btn ghost" href="#learn" data-act="go" data-to="learn">Reading room</a>`,
    onDone: (score, n) => {
      const g = G(); const rec = g.reads[id] || {}; const first = !rec.q; Daily.bump('read');
      rec.q = Math.max(rec.q || 0, score); g.reads[id] = rec;
      if (score === n && !rec.bonus) { rec.bonus = 1; g.pearls += 2; setTimeout(() => { FX.burst(innerWidth / 2, innerHeight * 0.45, 70); toast('Perfect reading: +2 pearls'); }, 300); }
      else if (first) { g.pearls += 1; toast('Reading finished: +1 pearl'); }
      save();
    },
  });
}

