  window.DragonRulesV12 = (() => {
    const RANDOM_LINES=[
      {zh:'發瘋啦！嚴厲斥責',en:'You’ve lost it! Strongly condemned!'},
      {zh:'中山羌',en:'Zhongshan muntjac!'},
      {zh:'伊爹伊爹',en:'Ouch, ouch!'},
      {zh:'啥鬼',en:'What the heck?'},
      {zh:'太神啦阿鬼',en:'That’s god-tier, A-Gui!'},
      {zh:'再怎麼痛，也不比失去弟弟心痛',en:'No matter how much this hurts, it hurts less than losing my little brother.'},
      {zh:'相戀是會呼吸的痛',en:'Being in love is a pain that breathes.'},
      {zh:'哀痛不是我的Tone',en:'Sorrow isn’t my tone.'},
      {zh:'釘O支啊！',en:'Ding O-zhi!'},
      {zh:'很癢ㄟ，雜魚',en:'That tickles, small fry.'}
    ];
    const THRESHOLDS=[
      {pct:75,zh:'你以為你是誰= =',en:'Who do you think you are = ='},
      {pct:67,zh:'六七！',en:'Six-seven!'},
      {pct:60,zh:'阿不就剛好及格',en:'So… I just barely passed.'},
      {pct:50,zh:'你以為我不會反擊嗎？',en:'You think I can’t fight back?'},
      {pct:40,zh:'啊啊啊啊啊啊',en:'AAAAAAAH!'},
      {pct:30,zh:'不…不可能',en:'N-no… impossible.'},
      {pct:20,zh:'我要生氣了',en:'I’m getting angry.'},
      {pct:10,zh:'不…不..不可能！',en:'N-no… n-no way!'},
      {pct:5,zh:'不要打死我..嗚嗚嗚',en:'Don’t kill me… sob…'},
      {pct:1,zh:'…傳承我的…意志',en:'…Carry on… my will.'}
    ];
    const MODE={
      normal:{zh:'正常',en:'Normal'},
      angry:{zh:'發怒',en:'Angry'},
      rage:{zh:'暴怒',en:'Enraged'},
      cry:{zh:'哭泣',en:'Crying'}
    };
    const modeForPct=(pct)=>pct<=5?'cry':pct<=10?'rage':pct<=20?'angry':'normal';
    const itemsEnabled=(mode)=>mode==='normal'||mode==='cry';
    const shieldLayers=(blocks)=>blocks>0?Math.ceil(blocks/2):0;
    function thresholdLine(prevPct,nextPct,fired={}){
      const crossed=THRESHOLDS.filter(t=>prevPct>t.pct&&nextPct<=t.pct&&!fired[t.pct]);
      if(!crossed.length)return null;
      const chosen=[...crossed].sort((a,b)=>a.pct-b.pct)[0];
      crossed.forEach(t=>{fired[t.pct]=true;});
      return chosen;
    }
    function randomLine(rng=Math.random){return RANDOM_LINES[Math.max(0,Math.min(RANDOM_LINES.length-1,Math.floor(rng()*RANDOM_LINES.length)))]||RANDOM_LINES[0];}
    function pickLine(prevPct,nextPct,fired={},rng=Math.random){return thresholdLine(prevPct,nextPct,fired)||randomLine(rng);}
    function attackDamage(base,mode,gongwanBoost){const tm=(window.TitleSystem&&typeof TitleSystem.attackMultiplier==='function')?TitleSystem.attackMultiplier():1;let n=base*tm*(gongwanBoost?(mode==='cry'?10:5):1);if(mode==='cry')n*=.5;return Math.max(1,Math.round(n));}
    /* Phase gates prevent a huge combo from skipping Angry / Enraged / Crying entirely. */
    function phaseFloorBoss(mode){return mode==='normal'?2000:mode==='angry'?1000:mode==='rage'?500:0;}
    function phaseBoundedDamage(boss,raw,mode){const floor=phaseFloorBoss(mode);const room=Math.max(0,Number(boss)||0-floor);return Math.max(0,Math.min(Math.max(0,Math.round(raw||0)),floor>0?room:Math.max(0,Number(boss)||0)));}
    return {RANDOM_LINES,THRESHOLDS,MODE,modeForPct,itemsEnabled,shieldLayers,thresholdLine,randomLine,pickLine,attackDamage,phaseFloorBoss,phaseBoundedDamage};
  })();
