  /* ---------- v13: dragon entrance + tragic battle music ---------- */
  const DRAGON_INTRO_MS=2600;
  let dragonIntroToken=0;
  const DragonBGM = {
    audio:null,active:false,monitor:0,fadeRAF:0,hiddenPause:false,
    ensure(){
      if(this.audio)return this.audio;
      const a=new Audio('soundscape/music_boss.mp3');a.loop=true;a.preload='auto';a.playsInline=true;a.volume=0;
      a.addEventListener('error',()=>{if(this.active)setTimeout(()=>this.recover(),450);});
      a.addEventListener('stalled',()=>{if(this.active)setTimeout(()=>this.recover(),700);});
      this.audio=a;return a;
    },
    allowed(){return !!(S.set.music&&st().music&&soundOptIn());},
    start(){
      this.active=true;this.hiddenPause=false;if(!this.allowed())return;
      const a=this.ensure();
      try{if(a.ended||!Number.isFinite(a.currentTime))a.currentTime=0;}catch(_){}
      const p=a.play();if(p&&p.catch)p.catch(()=>setTimeout(()=>{if(this.active&&this.allowed())this.recover();},220));
      this.watch();
    },
    watch(){
      if(this.monitor)return;
      this.monitor=setInterval(()=>{
        if(!this.active){clearInterval(this.monitor);this.monitor=0;return;}
        const a=this.audio;if(!a)return;
        if(!this.allowed()){if(!a.paused)a.pause();a.volume=0;return;}
        if(document.hidden)return;
        if(a.paused&&!this.hiddenPause){const p=a.play();if(p&&p.catch)p.catch(()=>{});}
        const voiceBusy=!!AudioEng.src||!!(window.speechSynthesis&&window.speechSynthesis.speaking);
        const target=voiceBusy?.045:.165;
        a.volume=Math.max(0,Math.min(1,a.volume+(target-a.volume)*.22));
      },90);
    },
    recover(){
      if(!this.active||!this.allowed()||document.hidden)return;
      const old=this.audio;let at=0;try{at=old&&Number.isFinite(old.currentTime)?old.currentTime:0;}catch(_){}
      try{old&&old.pause();}catch(_){} this.audio=null;
      const a=this.ensure();try{a.currentTime=Math.max(0,at-.12);}catch(_){}const p=a.play();if(p&&p.catch)p.catch(()=>{});this.watch();
    },
    pauseForHidden(){if(!this.active||!this.audio)return;this.hiddenPause=true;try{this.audio.pause();}catch(_){}},
    resumeFromHidden(){if(!this.active)return;this.hiddenPause=false;if(this.allowed()){const a=this.ensure();const p=a.play();if(p&&p.catch)p.catch(()=>{});this.watch();}},
    stop(){
      this.active=false;this.hiddenPause=false;if(this.monitor){clearInterval(this.monitor);this.monitor=0;}
      const a=this.audio;if(!a)return;const from=a.volume,start=performance.now();
      cancelAnimationFrame(this.fadeRAF);
      const fade=(now)=>{const k=Math.min(1,(now-start)/520);a.volume=Math.max(0,from*(1-k));if(k<1&&this.audio===a)this.fadeRAF=requestAnimationFrame(fade);else{try{a.pause();a.currentTime=0;}catch(_){}if(this.audio===a)this.audio=null;}};
      this.fadeRAF=requestAnimationFrame(fade);
    }
  };
