/* =====================================================================
   閒台文 · FX layer
   page mastheads, split-text reveals, cursor follower, magnetic buttons,
   scroll progress, back-to-top, Taipei clock, footer, 404
   ===================================================================== */
const UIFX = (() => {
  const FINE = window.matchMedia ? matchMedia('(hover:hover) and (pointer:fine)') : { matches: false };
  // page index + the big glyph printed behind each page title
  const MAST = { learn: ['01', '講'], situations: ['02', '境'], dictionary: ['03', '字'], taiwanese: ['04', '台'], culture: ['05', '文'], progress: ['07', '進'], profile: ['08', '我'] };

  /* ---------- split text: words (Latin) or characters (Chinese) rise in ---------- */
  const HAN = /[㐀-鿿豈-﫿㄀-ㄯ　-〿！-～]/;
  let splitIO = null;
  function unit(node, k) {
    const sw = document.createElement('span'); sw.className = 'sw';
    const si = document.createElement('span'); si.className = 'si'; si.style.setProperty('--k', Math.min(k, 26));
    si.appendChild(node); sw.appendChild(si); return sw;
  }
  function split(el) {
    if (!el || el.dataset.split || REDUCE) return;
    el.dataset.split = '1'; el.classList.add('split');
    let k = 0;
    const walk = (parent) => {
      [...parent.childNodes].forEach((n) => {
        if (n.nodeType === 3) {
          const frag = document.createDocumentFragment();
          n.textContent.split(/(\s+)/).forEach((p) => {
            if (!p) return;
            if (/^\s+$/.test(p)) { frag.appendChild(document.createTextNode(' ')); return; }
            if (HAN.test(p)) {
              // Chinese: one unit per character, but keep Latin runs inside the token together
              p.match(/[㐀-鿿豈-﫿㄀-ㄯ　-〿！-～]|[^㐀-鿿豈-﫿㄀-ㄯ　-〿！-～]+/g).forEach((c) => frag.appendChild(unit(document.createTextNode(c), k++)));
            } else frag.appendChild(unit(document.createTextNode(p), k++));
          });
          parent.replaceChild(frag, n);
        } else if (n.nodeType === 1) {
          if (n.matches('.h')) { const ph = document.createComment(''); parent.replaceChild(ph, n); parent.replaceChild(unit(n, k++), ph); }
          else if (!n.matches('svg, br, .sr, .sw')) walk(n);
        }
      });
    };
    walk(el);
    if (!splitIO && 'IntersectionObserver' in window) splitIO = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('go'); splitIO.unobserve(e.target); } }), { rootMargin: '0px 0px -6% 0px' });
    if (splitIO) splitIO.observe(el); else el.classList.add('go');
  }

  /* ---------- page masthead ---------- */
  function mast(app, r) {
    const m = MAST[r.v]; if (!m) return;
    const head = app.querySelector('.view > .sec-head:first-child, .view > .tri-standard:first-child + .sec-head'); if (!head || head.classList.contains('mast')) return;
    head.classList.add('mast');
    const eb = head.querySelector('.eyebrow'); if (eb) eb.insertAdjacentHTML('afterbegin', `<span class="mast-no">No.${m[0]}</span>`);
    head.insertAdjacentHTML('beforeend', `<span class="mast-glyph" aria-hidden="true" lang="zh-Hant">${m[1]}</span>`);
  }

  /* ---------- cursor follower (mouse only) ---------- */
  const Cur = { el: null, lab: null, x: -99, y: -99, tx: -99, ty: -99, raf: 0, mode: '' };
  const LABEL = { play: '聽 Listen', draw: '抽 Draw', drag: '拖 Drag', view: '看 Open' };
  function cursorMode(t) {
    if (!t || !t.closest) return '';
    if (t.closest('input, textarea, select, [contenteditable="true"]')) return 'text';
    if (t.closest('.play')) return 'play';
    if (t.closest('#cb-canvas')) return 'draw';
    if (t.closest('.gs-pill, .lens')) return 'drag';
    if (t.closest('a.card, a.spot, .handout-card, .art-card, .sit-card')) return 'view';
    if (t.closest('a, button, [role="button"], label, summary, select, [data-act]')) return 'link';
    return '';
  }
  function cursorTick() {
    Cur.x += (Cur.tx - Cur.x) * 0.24; Cur.y += (Cur.ty - Cur.y) * 0.24;
    Cur.el.style.transform = `translate3d(${Cur.x.toFixed(1)}px,${Cur.y.toFixed(1)}px,0)`;
    Cur.raf = Math.abs(Cur.tx - Cur.x) + Math.abs(Cur.ty - Cur.y) > 0.15 ? requestAnimationFrame(cursorTick) : 0;
  }
  function initCursor() {
    if (!FINE.matches || REDUCE) return;
    const el = document.createElement('div'); el.className = 'cur'; el.setAttribute('aria-hidden', 'true');
    el.innerHTML = '<i class="cur-ring"></i><b class="cur-lab" lang="zh-Hant"></b><i class="cur-dot"></i>';
    document.body.appendChild(el); Cur.el = el; Cur.lab = el.querySelector('.cur-lab');
    addEventListener('pointermove', (e) => {
      if (e.pointerType && e.pointerType !== 'mouse') return;
      Cur.tx = e.clientX; Cur.ty = e.clientY;
      if (!el.classList.contains('on')) { Cur.x = Cur.tx; Cur.y = Cur.ty; el.classList.add('on'); }
      if (!Cur.raf) Cur.raf = requestAnimationFrame(cursorTick);
    }, { passive: true });
    document.addEventListener('pointerover', (e) => {
      const m = cursorMode(e.target); if (m === Cur.mode) return;
      Cur.mode = m; el.dataset.m = m; Cur.lab.textContent = LABEL[m] || '';
    });
    document.documentElement.addEventListener('mouseleave', () => el.classList.remove('on'));
    addEventListener('pointerdown', () => el.classList.add('down'), { passive: true });
    addEventListener('pointerup', () => el.classList.remove('down'), { passive: true });
  }

  /* ---------- magnetic buttons ---------- */
  function initMagnet() {
    if (!FINE.matches || REDUCE) return;
    let cur = null;
    const release = () => { if (cur) { cur.style.translate = ''; cur = null; } };
    addEventListener('pointermove', (e) => {
      const b = e.target.closest && e.target.closest('.btn-hero, .btn.pri, .mag');
      if (b !== cur) release();
      if (!b || b.disabled) return; cur = b;
      const r = b.getBoundingClientRect();
      const dx = (e.clientX - (r.left + r.width / 2)) / r.width, dy = (e.clientY - (r.top + r.height / 2)) / r.height;
      b.style.translate = `${(dx * 12).toFixed(1)}px ${(dy * 9).toFixed(1)}px`;
    }, { passive: true });
    document.addEventListener('pointerleave', release);
  }

  /* ---------- scroll progress + back to top ---------- */
  let sRaf = 0;
  function onScrollFx() {
    if (sRaf) return;
    sRaf = requestAnimationFrame(() => {
      sRaf = 0;
      const h = document.documentElement.scrollHeight - innerHeight;
      document.documentElement.style.setProperty('--sp', h > 40 ? Math.min(1, scrollY / h).toFixed(4) : 0);
      const t = document.getElementById('to-top'); if (t) t.classList.toggle('show', scrollY > innerHeight * 1.3);
    });
  }

  /* ---------- Taipei clock in the footer ---------- */
  let clockT = 0;
  function tick() {
    let s = '';
    try { s = new Intl.DateTimeFormat('zh-TW', { timeZone: 'Asia/Taipei', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date()); } catch (e) { s = ''; }
    $$('[data-tpe]').forEach((el) => { el.textContent = s; });
    try { if(window.EasterEggs) EasterEggs.taipeiTime(s); } catch (_) {}
  }

  function mount(app, r) {
    mast(app, r);
    $$('.mast h1, .sec-head h2.h2, .f-title, [data-split]', app).forEach(split);
    tick(); clearInterval(clockT); clockT = setInterval(tick, 30000);
    onScrollFx();
  }
  function init() {
    initCursor(); initMagnet();
    addEventListener('scroll', onScrollFx, { passive: true }); addEventListener('resize', onScrollFx, { passive: true });
  }
  return { init, mount, split };
})();

/* ---------- footer (shared by every page) ---------- */
function footer() {
  const L = (to, zh, en) => `<a href="#${to}" data-act="go" data-to="${to}"><span lang="zh-Hant">${zh}</span><small>${en}</small></a>`;
  const B = (act, zh, en) => `<button type="button" data-act="${act}"><span lang="zh-Hant">${zh}</span><small>${en}</small></button>`;
  const tape = ['要辣嗎？', '半糖少冰', '不好意思，借過。', '真的假的？', '下一站，台北車站。', '歡迎光臨！', '食飽未？', '到家跟我說喔。'];
  const row = tape.map((t) => `<span lang="zh-Hant">${t}</span><i aria-hidden="true">✦</i>`).join('');
  return `<footer class="foot foot2">
    <div class="f-tape" aria-hidden="true"><div class="f-tape-track">${row}${row}</div></div>
    <div class="f-top">
      <div class="f-cta">
        <div class="eyebrow">閒台文 · Xián Tái Wén</div>
        <h2 class="f-title">Say it way <em>Taiwan</em> say it</h2>
        <p class="f-sub" lang="zh-Hant">用台灣人真正在說的方式，說中文。</p>
        <div class="f-actions"><button type="button" class="btn pri" data-act="share">${SHARE_ICON}<span>分享閒台文</span></button><a class="btn ghost" href="#practice" data-act="go" data-to="practice">抽一張卡 ${I.arrow}</a></div>
      </div>
      <nav class="f-cols" aria-label="Site map">
        <div><h3><span lang="zh-Hant">學</span> Learn</h3>${L('learn', '講義', 'Handouts')}${L('situations', '情境', 'Situations')}${L('dictionary', '字典', 'Dictionary')}${L('taiwanese', '台語', 'Taiwanese')}${L('culture', '文化', 'Culture')}</div>
        <div><h3><span lang="zh-Hant">練</span> Practice</h3>${L('practice', '抽卡闖關', 'Card box')}${L('academy', '闖關學院', 'Academy')}${L('academy.people', '人物圖鑑', 'People')}${L('progress', '進度', 'Progress')}</div>
        <div><h3><span lang="zh-Hant">站</span> Site</h3>${L('about', '關於我們', 'About us')}${L('privacy', '隱私與個資', 'Privacy')}${B('share', '分享', 'Share')}${B('welcome', '重看歡迎頁', 'Welcome tour')}${L('profile', '設定', 'Settings')}${B('top', '回到頂端', 'Back to top')}</div>
      </nav>
    </div>
    <div class="f-word" aria-hidden="true" lang="zh-Hant"><span>閒</span><span>台</span><span>文</span></div>
    <div class="f-base"><span>© 2026 閒台文 Xián Tái Wén</span><span>For everyone learning the Mandarin Taiwan actually speaks.</span><span class="f-clock"><i aria-hidden="true"></i>台北 Taipei <b class="num" data-tpe></b></span></div>
  </footer>`;
}

