    const u = url();
    el.innerHTML = html(u); el.hidden = false; el.classList.remove('out');
    document.documentElement.classList.add('sh-lock');
    requestAnimationFrame(() => { paintQR(el.querySelector('.tk-qr'), u); const b = el.querySelector('[data-sh="copy"]'); if (b) b.focus({ preventScroll: true }); });
    syncImageButton();
