        <div class="wl-goals" role="radiogroup" aria-labelledby="wl-h2">${GOALS.map((g, i) => `<button type="button" class="wl-goal ${goal === g[0] ? 'sel' : ''}" role="radio" aria-checked="${goal === g[0]}" data-wl="goal" data-g="${g[0]}" style="--i:${i}"><span class="wl-goal-no num">0${i + 1}</span><b lang="zh-Hant">${g[1]}</b><span class="wl-goal-en">${g[2]}</span><span class="wl-goal-d">${g[3]}</span><span class="wl-goal-go">Start with ${g[5]} ${I.arrow}</span><i class="wl-tick" aria-hidden="true">${I.check}</i></button>`).join('')}</div>
