    const next = el.querySelector('.wl-next span');
    next.textContent = step === 0 ? '開始 Let’s go' : step === 4 ? '進入閒台文 Enter' : '下一步 Next';
    el.querySelector('.wl-next').classList.toggle('wait', (step===1&&!S.gender)||(step===2&&!S.goal));
    if (step === 3) { const r = el.querySelector('[data-gs]'); if (r && !r._gs) initGS(r); else if (r && r._gs) r._gs.relayout(); }
    if (step === 4 && soundOptIn()) { const h=el.querySelector('.wl-heard'); if(h){h.hidden=false; h.innerHTML=`${I.check} Sound is on · music will continue across the site`;} }
    const s = el.querySelector(`.wl-step[data-step="${step}"]`);
    $$('[data-wsplit]', s).forEach((h) => { UIFX.split(h); requestAnimationFrame(() => h.classList.add('go')); });
